import { Component } from '@angular/core';
import { RouterModule } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';


export interface Reclamation {
  id: string;
  clientName: string;
  clientPhone: string;
  offerType: 'ADSL' | 'VDSL' | 'Fibre' | 'HexaPro';
  issueType: string;
  priority: 'Haute' | 'Moyenne' | 'Basse';
  status: 'En attente' | 'En cours' | 'Résolue';
  createdAt: string;
}

export interface NotificationItem {
  id: number;
  message: string;
  time: string;
  unread: boolean;
}

@Component({
  selector: 'app-zone',
  templateUrl: './zone.component.html',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterModule],
  styleUrls: ['./zone.component.css']
})
export class ZoneComponent {

  // Informations de l'agent connecté
  agentName: string = 'Karim Mansour';
  agentRole: string = 'Agent Support Senior';

  // Horloge dynamique au format 12h (01h - 12h AM/PM)
  currentTimeFormatted: string = '';
  private clockInterval: any;

  // Gestion des notifications
  showNotifications: boolean = false;
  notifications: NotificationItem[] = [
    { id: 1, message: 'Nouvelle réclamation urgente (Fibre Optique)', time: 'Il y a 5 min', unread: true },
    { id: 2, message: 'Technicien assigné à la Zone #04', time: 'Il y a 20 min', unread: true },
    { id: 3, message: 'Ticket #HEX-2026-099 résolu avec succès', time: 'Il y a 1h', unread: false }
  ];

  // Filtres et Recherche pour les réclamations
  searchTerm: string = '';
  selectedStatusFilter: string = 'Tous';

  // Liste des réclamations Hexabyte
  reclamations: Reclamation[] = [
    {
      id: 'HEX-2026-101',
      clientName: 'Sami Ben Ali',
      clientPhone: '+216 98 123 456',
      offerType: 'Fibre',
      issueType: 'Coupure totale de signal ONT',
      priority: 'Haute',
      status: 'En attente',
      createdAt: 'Aujourd\'hui à 09:15'
    },
    {
      id: 'HEX-2026-102',
      clientName: 'Mouna Trabelsi',
      clientPhone: '+216 55 987 654',
      offerType: 'ADSL',
      issueType: 'Chute de débit sévère',
      priority: 'Moyenne',
      status: 'En cours',
      createdAt: 'Aujourd\'hui à 08:40'
    },
    {
      id: 'HEX-2026-103',
      clientName: 'Société AgroTech',
      clientPhone: '+216 71 333 444',
      offerType: 'HexaPro',
      issueType: 'Configuration adresse IP fixe',
      priority: 'Haute',
      status: 'En cours',
      createdAt: 'Hier à 16:30'
    },
    {
      id: 'HEX-2026-104',
      clientName: 'Yassine Gharbi',
      clientPhone: '+216 22 456 789',
      offerType: 'VDSL',
      issueType: 'Pertes de paquets fréquentes',
      priority: 'Basse',
      status: 'Résolue',
      createdAt: 'Hier à 14:10'
    },
    {
      id: 'HEX-2026-105',
      clientName: 'Ines Bouaziz',
      clientPhone: '+216 97 888 111',
      offerType: 'ADSL',
      issueType: 'Erreur d\'authentification PPPoE',
      priority: 'Moyenne',
      status: 'En attente',
      createdAt: 'Aujourd\'hui à 10:05'
    }
  ];

  ngOnInit(): void {
    this.updateClock();
    this.clockInterval = setInterval(() => this.updateClock(), 1000);
  }

  ngOnDestroy(): void {
    if (this.clockInterval) {
      clearInterval(this.clockInterval);
    }
  }

  // Horloge au format 12 heures (01:00:00 AM/PM - 12:59:59 AM/PM)
  private updateClock(): void {
    const now = new Date();
    let hours = now.getHours();
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');
    const ampm = hours >= 12 ? 'PM' : 'AM';

    hours = hours % 12;
    hours = hours ? hours : 12; // Si 0 heure, afficher 12
    const hoursFormatted = String(hours).padStart(2, '0');

    this.currentTimeFormatted = `${hoursFormatted}:${minutes}:${seconds} ${ampm}`;
  }

  get unreadNotificationsCount(): number {
    return this.notifications.filter(n => n.unread).length;
  }

  markAllAsRead(): void {
    this.notifications.forEach(n => n.unread = false);
  }

  // Obtenir les réclamations filtrées
  get filteredReclamations(): Reclamation[] {
    return this.reclamations.filter(rec => {
      const matchesSearch = 
        rec.clientName.toLowerCase().includes(this.searchTerm.toLowerCase()) ||
        rec.id.toLowerCase().includes(this.searchTerm.toLowerCase()) ||
        rec.issueType.toLowerCase().includes(this.searchTerm.toLowerCase());

      const matchesStatus = 
        this.selectedStatusFilter === 'Tous' || 
        rec.status === this.selectedStatusFilter;

      return matchesSearch && matchesStatus;
    });
  }
}
